        Money.Zero, totalAmount, actorUser.Name, authorization.Approver?.ApproverName, null, null, null, null, shiftValue.Piastres, ct);
    if (entity is null)
    {
        // Same idempotent-replay reasoning as RecordOvertimeHandler above.
        var replay = await _db.EmployeeLedgerEntries.AsNoTracking().FirstAsync(e => e.Id == id, ct);
        return EmployeeQueryService.ToLedgerDto(replay);
    }
    await _db.SaveChangesAsync(ct);
    return EmployeeQueryService.ToLedgerDto(entity);

public async Task<EmployeeLedgerEntryDto> HandleAsync(RecordManualLedgerEntryRequest request, CancellationToken ct = default)
{
    // Parsed leniently, stored canonically. The type used to be validated case-insensitively
    // and then written down exactly as it arrived, so a bonus recorded as "bonus" was accepted,
    // appeared on the employee's statement, and was then skipped by the payroll calculation -
    // which matches "Bonus". The employee simply did not get paid it, and nothing anywhere said
    // so. Whatever casing the caller uses, one spelling reaches the database.
    if (!Enum.TryParse<LedgerEntryType>(request.Type, ignoreCase: true, out var entryType))
        throw new DomainException("نوع حركة كشف الحساب غير صالح.");
    var canonicalType = entryType.ToString();
    var amount = Money.FromPiastres(request.AmountPiastres);
    EmployeeRules.AssertLedgerAmount(amount);
    if (string.IsNullOrWhiteSpace(request.Description)) throw new DomainException("وصف الحركة مطلوب.");

        var authorization = AuthorizationPolicy.AuthorizeCommand(_approvalRegistry, actor, "employees_ledger", approval, requireApproval: true);

        var currentBalance = Money.FromPiastres(await _db.EmployeeLedgerEntries.AsNoTracking()
            .Where(e => e.EmployeeId == request.EmployeeId)
            .Select(e => e.CreditPiastres - e.DebitPiastres).SumAsync(ct));
        var debit = request.IsCredit ? Money.Zero : amount;
        var credit = request.IsCredit ? amount : Money.Zero;
        var newBalance = currentBalance + credit - debit;

        var entity = new EmployeeLedgerEntryEntity
        {
            Id = $"led-{Guid.NewGuid():N}", EmployeeId = request.EmployeeId, Type = canonicalType,
            Description = request.Description.Trim(), DebitPiastres = debit.Piastres, CreditPiastres = credit.Piastres,
            BalanceAfterPiastres = newBalance.Piastres, RecordedBy = actorUser.Name,
            AuthorizedBy = authorization.Approver?.ApproverName, CreatedAtUtc = DateTimeOffset.UtcNow,
        };
        _db.EmployeeLedgerEntries.Add(entity);
        await _db.SaveChangesAsync(ct);
        return EmployeeQueryService.ToLedgerDto(entity);

public static async Task<Money> GetCurrentBalanceAsync(FalahDbContext db, string employeeId, CancellationToken ct)
{
    var entries = await db.EmployeeLedgerEntries.AsNoTracking().Where(e => e.EmployeeId == employeeId)
        .Select(e => new { e.CreditPiastres, e.DebitPiastres }).ToListAsync(ct);
    // A single command can append more than one movement before SaveChanges (for
    // example, a late penalty followed by overtime). Include its earlier pending
    // appends, otherwise the second row's displayed running balance omits the first.
    var pendingDelta = db.ChangeTracker.Entries<EmployeeLedgerEntryEntity>()
        .Where(e => e.State == EntityState.Added && e.Entity.EmployeeId == employeeId)
        .Sum(e => e.Entity.CreditPiastres - e.Entity.DebitPiastres);
    return Money.FromPiastres(entries.Sum(e => e.CreditPiastres - e.DebitPiastres) + pendingDelta);
}

/// <summary>Returns null (posts nothing) if an entry with this exact Id already exists - the
/// deterministic-id dedup that makes a retried biometric event or duplicate correction a safe
/// no-op rather than a double-post.</summary>
public static async Task<EmployeeLedgerEntryEntity?> PostIfNewAsync(
    FalahDbContext db, string id, string employeeId, string type, string description, Money debit, Money credit,
    string recordedBy, string? authorizedBy, string? shiftId, string? referenceId, double? hours,
    long? rateSnapshotPiastres, long? valueSnapshotPiastres, CancellationToken ct)
{
    if (db.EmployeeLedgerEntries.Local.Any(e => e.Id == id)
        || await db.EmployeeLedgerEntries.AsNoTracking().AnyAsync(e => e.Id == id, ct)) return null;

    var currentBalance = await GetCurrentBalanceAsync(db, employeeId, ct);
    var newBalance = currentBalance + credit - debit;
    var entity = new EmployeeLedgerEntryEntity
    {
        Id = id, EmployeeId = employeeId, Type = type, Description = description,
        DebitPiastres = debit.Piastres, CreditPiastres = credit.Piastres, BalanceAfterPiastres = newBalance.Piastres,
        RecordedBy = recordedBy, AuthorizedBy = authorizedBy, ShiftId = shiftId, ReferenceId = referenceId,
        Hours = hours, RateSnapshotPiastres = rateSnapshotPiastres, ValueSnapshotPiastres = valueSnapshotPiastres,
        CreatedAtUtc = DateTimeOffset.UtcNow,
    };
    db.EmployeeLedgerEntries.Add(entity);

